import{z as B,x as m,o as i,c as p,q as r,j as o,D as n,d as l,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"二项堆","description":"","frontmatter":{"title":"二项堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/binomial-heap.md","filePath":"cs/binomial-heap.md","lastUpdated":1791413859000}'),E={name:"cs/binomial-heap.md"};function A(_,a,u,c,T,h){const t=m("Mermaid");return i(),p("div",null,[a[2]||(a[2]=r('<h1 id="二项堆" tabindex="-1">二项堆 <a class="header-anchor" href="#二项堆" aria-label="Permalink to &quot;二项堆&quot;">​</a></h1><div class="epigraph"><p>一棵二项树 $B_k$ 有 $2^k$ 个节点；堆是不同秩的 $B_k$ 之林，合并像二进制加法进位。</p><footer>—— 据 Vuillemin, A Data Structure for Manipulating Priority Queues, CACM 1978；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/fibonacci-heap">上一课</a>用懒合并与标记换摊还 \\(O(1)\\) 减键。要理解「按度数合并」，更干净的模型是二项堆：每秩至多一棵，meld 最坏 \\(O(\\log n)\\)。本课不级联割。缺口是 Vuillemin 二项堆：形状由二进制唯一决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(B_0\\) 单节点；\\(B_k\\) 是一个根挂上 \\(B_0,\\ldots,B_{k-1}\\)（或两个 \\(B_{k-1}\\) 按堆序链接）。节点数 \\(2^k\\)。二项堆 = 一组根，秩互异，各满足堆序。\\(n\\) 的二进制里有几个 1，林里就几棵树。meld：从小秩到大秩，同秩两棵链接成秩 \\(+1\\)，与加法进位相同。缺口是<strong>把可并堆做成二进制计数器</strong>，分析不必斐波那契。</p><p><span class="marginnote">直觉类比：把每棵二项树想成一个「二进制位」——第 \\(k\\) 位有树就记 1。两堆合并时同秩两棵相遇，链接成一棵秩 \\(+1\\) 的树，恰好像 \\(1+1=0\\) 进一位：堆的合并就是一次二进制加法。</span></p><p><span class="marginnote">CLRS 第 19 章先讲二项再讲斐波那契。insert 是 meld 一个 \\(B_0\\)，摊还可 \\(O(1)\\)，最坏 \\(O(\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>find-min：扫根表 \\(O(\\log n)\\) 棵。extract-min：摘最小根，其孩子是较小秩的二项堆，与剩余 meld。decrease-key：上滤，与二叉堆同，最坏 \\(O(\\log n)\\)，没有 Fib 的 \\(O(1)\\) 摊还。</p><p><span class="marginnote">数字实例：\\(n=13\\) 的堆有 3 棵根（对应二进制 1101），find-min 最多比 3 次；\\(n\\) 翻倍只多比约 1 次——这就是「扫根表 \\(O(\\log n)\\)」的具体含义。</span></p>',10)),(i(),o(d,null,{default:n(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BK%5B%22B_k%20%3D%20%E6%A0%B9%20%2B%20B_0..B_%7Bk-1%7D%22%5D%20--%3E%20FOREST%5B%22%E4%B8%8D%E5%90%8C%E7%A7%A9%E4%B9%8B%E6%9E%97%22%5D%0A%20%20MELD%5B%22meld%22%5D%20--%3E%20CARRY%5B%22%E5%90%8C%E7%A7%A9%E9%93%BE%E6%8E%A5%20%3D%20%E8%BF%9B%E4%BD%8D%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与左偏：二项形状更死、证明更短；左偏树高也对数但不是 \\(2^k\\) 块。与 Fib：Fib 允许同秩多棵（根表懒），consolidate 才压成类似二项。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"链接：键大的根做键小的根的新孩子，秩加一。孩子表通常按秩有序，extract-min 时反转孩子链即可得合法二项堆。这是后课「可并堆 ADT」的标准实现之一。",-1)),a[6]||(a[6]=e("p",null,"形状怎么由 \\(n\\) 的二进制唯一决定：",-1)),(i(),o(d,null,{default:n(()=>[s(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22n%20%3D%2013%20%3D%20%E4%BA%8C%E8%BF%9B%E5%88%B6%201101%22%5D%20--%3E%20T3%5B%22B_3%EF%BC%9A8%20%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%0A%20%20N%20--%3E%20T2%5B%22B_2%EF%BC%9A4%20%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%0A%20%20N%20--%3E%20T0%5B%22B_0%EF%BC%9A1%20%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%0A%20%20T3%20--%3E%20TOT%5B%22%E6%9E%97%EF%BC%9A3%20%E6%A3%B5%E6%A0%91%EF%BC%8C8%2B4%2B1%20%3D%2013%22%5D%0A%20%20T2%20--%3E%20TOT%0A%20%20T0%20--%3E%20TOT%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：以为 extract-min 删掉节点后要费力「修补」树形。实际摘走 \\(B_k\\) 的根后，剩下的孩子天然就是一组较小秩的二项树，只需与残余的林做 meld，不需要额外修复。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把斜二项、或 Brodal 堆写进来。decrease-key 不是本结构的强项——那是 Fib 的动机。下一课把 meld/insert/extract-min/decrease-key 收成一张合同表，对照已出现的实现。</p><p>后课默认：按秩合并的林就是二项堆图像。可并堆 ADT 与表示分离。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二项堆：二进制形状的可并堆，meld 如进位。</li><li>减键 \\(O(\\log n)\\)，不如 Fib 摊还。</li><li>下一课把可并堆合同钉死。</li><li>出处：Vuillemin, <em>CACM</em>, 1978；Cormen et al.。</li></ul>',6))])}const k=B(E,[["render",A]]);export{f as __pageData,k as default};
